// Block (composition) — a row of round quick-filter shortcuts, each an icon plate over a caption.
// Button's vertical orientation owns the plate, the caption and the press target; this Block only
// lines them up and lets the row scroll sideways when it outgrows its column.
import type { ReactNode, Ref } from "react";
import { Text } from "react-aria-components";
import { Button } from "../components/Button";
import { ScrollArea } from "../components/ScrollArea";
import { Stack } from "../layouts/Stack";
import "./QuickFilterRail.css";

interface QuickFilterBase {
  /** Stable key for the filter. */
  id: string;
  /** Caption under the plate; also the button's accessible name. */
  label: string;
}

/** An icon on the neutral plate, or an illustration that IS the plate: never both. */
export type QuickFilter = QuickFilterBase &
  (
    | {
        /** One decorative icon. Pass it with `aria-hidden`. */
        icon: ReactNode;
        image?: never;
      }
    | {
        icon?: never;
        /** An illustration filling the plate (its own background included), as a decorative image URL. */
        image: string;
      }
  );

export interface QuickFilterRailProps {
  /** The shortcuts, in reading order. */
  filters: QuickFilter[];
  /** Called with the chosen filter's `id`. */
  onSelect?: (id: string) => void;
  /** Accessible name of the row, since a row of shortcuts is a group. */
  "aria-label": string;
  className?: string;
  ref?: Ref<HTMLDivElement>;
}

export function QuickFilterRail({ filters, onSelect, "aria-label": ariaLabel, className, ref }: QuickFilterRailProps) {
  return (
    <ScrollArea
      ref={ref}
      orientation="horizontal"
      className={className ? `sd-quickfilterrail ${className}` : "sd-quickfilterrail"}
    >
      <Stack as="ul" direction="row" gap="medium" align="start" aria-label={ariaLabel} className="sd-quickfilterrail__list">
        {filters.map((filter) => (
          <li key={filter.id} className="sd-quickfilterrail__item">
            <Button orientation="vertical" variant="secondary" onPress={() => onSelect?.(filter.id)}>
              {filter.image ? <img src={filter.image} alt="" /> : filter.icon}
              <Text>{filter.label}</Text>
            </Button>
          </li>
        ))}
      </Stack>
    </ScrollArea>
  );
}

/* QuickFilterRail.css — .sd-quickfilterrail (Block)
   Arrangement only. Button owns the plate, caption and colours; ScrollArea owns the overflow. */
.sd-quickfilterrail__list {
  margin: 0;
  padding: 0;
  list-style: none;
}

/* A shortcut never shrinks to fit the row: the row scrolls instead, so a caption is never cut. */
.sd-quickfilterrail__item {
  flex: none;
}
